CREATE TABLE ARO_PROP_SCARTO_VERS (ID_PROP_SCARTO_VERS NUMBER GENERATED ALWAYS AS IDENTITY NOT NULL, ID_STRUT NUMBER NOT NULL, PG_PROP_SCARTO_VERS NUMBER, AA_PROP_SCARTO_VERS NUMBER GENERATED ALWAYS AS (EXTRACT(YEAR FROM DT_CREAZIONE)) NOT NULL, DS_PROP_SCARTO_VERS VARCHAR2(254 CHAR), NT_PROP_SCARTO_VERS VARCHAR2(2000 CHAR), ID_STATO_PROP_SCARTO_VERS_COR NUMBER, DT_CREAZIONE date NOT NULL, DT_ULTIMA_MOD date, CONSTRAINT PK_ARO_PROP_SCARTO_VERS PRIMARY KEY (ID_PROP_SCARTO_VERS));
COMMENT ON TABLE ARO_PROP_SCARTO_VERS IS 'Tabella per le Proposte di Scarto Versamenti';
COMMENT ON COLUMN ARO_PROP_SCARTO_VERS.ID_PROP_SCARTO_VERS IS 'Identificativo univoco PK';
COMMENT ON COLUMN ARO_PROP_SCARTO_VERS.ID_STRUT IS 'Identificativo della struttura di appartenenza (FK)';
COMMENT ON COLUMN ARO_PROP_SCARTO_VERS.DS_PROP_SCARTO_VERS IS 'Descrizione breve della proposta';
COMMENT ON COLUMN ARO_PROP_SCARTO_VERS.NT_PROP_SCARTO_VERS IS 'Motivazioni o note estese';
COMMENT ON COLUMN ARO_PROP_SCARTO_VERS.ID_STATO_PROP_SCARTO_VERS_COR IS 'Identificativo dello stato corrente della proposta (FK su ARO_STATO_PROP_SCARTO_VERS)';
COMMENT ON COLUMN ARO_PROP_SCARTO_VERS.DT_CREAZIONE IS 'Data di creazione del record';
COMMENT ON COLUMN ARO_PROP_SCARTO_VERS.DT_ULTIMA_MOD IS 'Data di ultima modifica del record';

-- changeset root:1780310394991-406 splitStatements:true
