COMMENT ON TABLE ARO_STATO_PROP_SCARTO_VERS IS 'Tabella dello storico degli stati delle Proposte di Scarto';
COMMENT ON COLUMN ARO_STATO_PROP_SCARTO_VERS.ID_STATO_PROP_SCARTO_VERS IS 'Identificativo univoco PK dello stato';
COMMENT ON COLUMN ARO_STATO_PROP_SCARTO_VERS.ID_PROP_SCARTO_VERS IS 'Identificativo della proposta di scarto associata (FK)';
COMMENT ON COLUMN ARO_STATO_PROP_SCARTO_VERS.PG_STATO_PROP_SCARTO_VERS IS 'Progressivo cronologico dello stato per quella proposta';
COMMENT ON COLUMN ARO_STATO_PROP_SCARTO_VERS.DT_REG_STATO_PROP_SCARTO_VERS IS 'Data di registrazione dello stato';
COMMENT ON COLUMN ARO_STATO_PROP_SCARTO_VERS.DS_NOTA_PROP_SCARTO_VERS IS 'Eventuali note o motivazioni per il cambio di stato';
COMMENT ON COLUMN ARO_STATO_PROP_SCARTO_VERS.TI_STATO_PROP_SCARTO_VERS IS 'Valore dello stato (es. BOZZA, INVIATA, ecc.)';
COMMENT ON COLUMN ARO_STATO_PROP_SCARTO_VERS.ID_USER_IAM IS 'Utente che ha effettuato il cambio di stato';

