CREATE OR REPLACE FORCE VIEW ARO_V_RIC_ADV_UNITA_DOC (ID_UNITA_DOC, ID_STRUT_UNITA_DOC, CD_REGISTRO_KEY_UNITA_DOC, AA_KEY_UNITA_DOC, CD_KEY_UNITA_DOC, ID_SUB_STRUT, DT_CREAZIONE, FL_UNITA_DOC_FIRMATO, TI_ESITO_VERIF_FIRME, DS_MSG_ESITO_VERIF_FIRME, ID_TIPO_UNITA_DOC, ID_STRUT_TIPO_UNITA_DOC, NM_TIPO_UNITA_DOC, FL_FORZA_ACCETTAZIONE, FL_FORZA_CONSERVAZIONE, DS_KEY_ORD, DL_OGGETTO_UNITA_DOC, DT_REG_UNITA_DOC, TI_CONSERVAZIONE, NM_SISTEMA_MIGRAZ, NI_ALLEG, NI_ANNESSI, NI_ANNOT, ID_DOC, TI_DOC, ID_TIPO_DOC, TI_STATO_DOC, DL_DOC, DS_AUTORE_DOC, CD_KEY_DOC_VERS, FL_FORZA_COLLEGAMENTO, CD_VERSIONE_WS, FL_AGG_META, NM_TIPO_DOC_PRINC, FL_DOC_AGGIUNTI, FL_UNITA_DOC_ANNUL, FL_DOC_ANNUL, TI_STATO_CONSERVAZIONE, TI_STATO_UD_ELENCO_VERS, TI_STATO_DOC_ELENCO_VERS, FL_HASH_VERS, DS_LISTA_STATI_ELENCO_VERS, FL_ESISTE_PROFILO_NORMATIVO) AS select
 -- ===============================================================================
 -- colonne unità documentaria
 ud.id_unita_doc, 
 ud.id_strut id_strut_unita_doc, ud.cd_registro_key_unita_doc, ud.aa_key_unita_doc, ud.cd_key_unita_doc, 
 ud.id_sub_strut,
 ud.dt_creazione,
 ud.fl_unita_doc_firmato,
 ud.ti_esito_verif_firme, ud.ds_msg_esito_verif_firme,
 ud.id_tipo_unita_doc, tipo_unita_doc.id_strut id_strut_tipo_unita_doc, tipo_unita_doc.nm_tipo_unita_doc, 
 ud.fl_forza_accettazione, ud.fl_forza_conservazione, 
 
 ud.ds_key_ord,
 
 ud.dl_oggetto_unita_doc,
 ud.dt_reg_unita_doc,
 ud.ti_conservazione,
 ud.nm_sistema_migraz,

 ud.ni_alleg, ud.ni_annessi, ud.ni_annot,
  
 -- ===============================================================================
 -- colonne documenti
 doc.id_doc,
 doc.ti_doc,
 doc.id_tipo_doc,
 doc.ti_stato_doc,
 
 doc.dl_doc,
 doc.ds_autore_doc,
 doc.cd_key_doc_vers,

--		colonne aggiunte 

 ud.fl_forza_collegamento,
 
 -- 30055
  (select ses.cd_versione_ws
  from VRS_SESSIONE_VERS ses  
  where ses.id_unita_doc = ud.id_unita_doc
 and ses.ti_sessione_vers = 'VERSAMENTO'
 ---and ses.ti_stato_sessione_vers = 'CHIUSA_OK' ---- da verificare se ha senso con le tabelle separate tra OK e KO
  ) cd_versione_ws,  
 
-- 27483
 case
	when exists (select 1
				 from ARO_UPD_UNITA_DOC upd_ud				 
				 where upd_ud.id_unita_doc = ud.id_unita_doc
				)
		then '1'
		else '0'
 end fl_agg_meta,


 (select tipo_doc_princ.nm_tipo_doc 
  from ARO_DOC doc_princ
  join DEC_TIPO_DOC tipo_doc_princ
   on (tipo_doc_princ.id_tipo_doc = doc_princ.id_tipo_doc)
  where doc_princ.id_unita_doc = ud.id_unita_doc
  and doc_princ.ti_doc = 'PRINCIPALE')  nm_tipo_doc_princ,

 case
	when ud.dt_creazione != doc.dt_creazione
		then '1'
		else '0'
 end fl_doc_aggiunti,
 
 case
	when ud.dt_annul = to_date('31/12/2444', 'dd/mm/yyyy') then '0' else '1'
 end fl_unita_doc_annul,
 case
	when doc.dt_annul = to_date('31/12/2444', 'dd/mm/yyyy') then '0' else '1'
 end fl_doc_annul,

--		colonne aggiunte 

 ud.ti_stato_conservazione,
 ud.ti_stato_ud_elenco_vers,
 doc.ti_stato_doc_elenco_vers,

 case
	when exists (select 1
				 from ARO_STRUT_DOC strut_doc
				 join ARO_COMP_DOC comp
				  on (comp.id_strut_doc = strut_doc.id_strut_doc
				  and comp.ds_hash_file_vers is not null)
				 where strut_doc.id_doc = doc.id_doc
				)
		then '1'
		else '0'
 end fl_hash_vers,

-- (select xsd.cd_versione_xsd
--  from ARO_USO_XSD_DATI_SPEC uso_xsd
--  join DEC_XSD_DATI_SPEC xsd
--   on (xsd.id_xsd_dati_spec = uso_xsd.id_xsd_dati_spec)
--  where uso_xsd.id_unita_doc = ud.id_unita_doc
--  and uso_xsd.ti_uso_xsd = 'VERS'
--  and uso_xsd.ti_entita_sacer = 'UNI_DOC'
--  ) cd_versione_xsd_ud,

-- (select xsd.cd_versione_xsd
--  from ARO_USO_XSD_DATI_SPEC uso_xsd
--  join DEC_XSD_DATI_SPEC xsd
--   on (xsd.id_xsd_dati_spec = uso_xsd.id_xsd_dati_spec)
--  where uso_xsd.id_doc = doc.id_doc
--  and uso_xsd.ti_uso_xsd = 'VERS'
--  and uso_xsd.ti_entita_sacer = 'DOC'
--  ) cd_versione_xsd_doc,

  (select 
   listagg (tmp.ti_stato_elenco_vers, '; ') within group (order by tmp.ti_stato_elenco_vers)
   from
		(select ud_elenco.ti_stato_ud_elenco_vers ti_stato_elenco_vers
		from ARO_UNITA_DOC ud_elenco
		where ud_elenco.id_unita_doc = ud.id_unita_doc
		UNION
		select doc_elenco.ti_stato_doc_elenco_vers ti_stato_elenco_vers
		from ARO_DOC doc_elenco
		where doc_elenco.id_unita_doc = ud.id_unita_doc
		and doc_elenco.ti_stato_doc_elenco_vers is not null
		)	tmp
  ) ds_lista_stati_elenco_vers,

 case
	when exists (select xms.id_xml_modello_sessione_vers from Vrs_Xml_Modello_Sessione_Vers xms 
                    join dec_uso_modello_xsd_uni_doc uso_modello_xsd_uni_doc on(xms.id_uso_modello_xsd_uni_doc = uso_modello_xsd_uni_doc.id_uso_modello_xsd_uni_doc)
                    join dec_Modello_Xsd_Ud modello_xsd  on (modello_xsd.id_modello_xsd_ud = uso_modello_xsd_uni_doc.id_modello_xsd_ud)
                    join vrs_Dati_Sessione_Vers dati_ses on(xms.id_dati_sessione_vers = dati_ses.id_dati_sessione_vers)
                    join vrs_Sessione_Vers ses on(ses.id_sessione_vers = dati_ses.id_sessione_vers)
                    where modello_xsd.ti_Uso_Modello_Xsd = 'VERS'
                    and modello_xsd.ti_Modello_Xsd = 'PROFILO_NORMATIVO_UNITA_DOC'
                    and dati_ses.ti_Dati_Sessione_Vers = 'XML_DOC'                   
                    --and ses.ti_Stato_Sessione_Vers = 'CHIUSA_OK' ---- da verificare se ha senso con le tabelle separate tra OK e KO
                    and ses.ti_Sessione_Vers = 'VERSAMENTO'
                    and ses.id_unita_doc = ud.id_unita_doc
                    and ses.id_doc is null
				)
		then '1'
		else '0'
 end fl_esiste_profilo_normativo

from ARO_UNITA_DOC ud
join DEC_TIPO_UNITA_DOC tipo_unita_doc
 on (tipo_unita_doc.id_tipo_unita_doc = ud.id_tipo_unita_doc)

join ARO_DOC doc
 on (doc.id_unita_doc = ud.id_unita_doc);

-- changeset root:1780310394991-410
CREATE OR REPLACE FORCE VIEW ARO_V_RIC_RICH_RA_2026 (ID_ENTE_CONVENZ, NM_ENTE_CONVENZ, NM_ENTE_STRUT, ID_RICHIESTA_RA, ID_AMBIENTE, ID_ENTE, ID_STRUT, TOTALI, ESTRATTI, ERRORI, SUM_DIM, MAX_DT_ESTRAZIONE, TI_STATO, ESTRATTI_TOTALI, CD_ERRORE, TS_INIZIO) AS WITH stats AS (
    /*+ MATERIALIZE */
    SELECT 
        reqs.ID_RICHIESTA_RA,
        udoc.ID_STRUT,
        -- Count e Sum fatti qui per ridurre le righe prima delle join anagrafiche
        COUNT(1) AS totali,
        SUM(CASE reqs.ti_stato WHEN 'ESTRATTO' THEN 1 ELSE 0 END) AS estratti,
        SUM(CASE reqs.ti_stato WHEN 'ERRORE' THEN 1 ELSE 0 END) AS errori,
        SUM(reqs.dim) AS sum_dim_raw,
        MAX(reqs.dt_estrazione) AS max_dt
    FROM aro_aip_restituzione_archivio reqs
    JOIN aro_indice_aip_ud aip ON reqs.id_indice_aip = aip.id_indice_aip
    JOIN aro_unita_doc udoc ON udoc.id_unita_doc = aip.id_unita_doc
    GROUP BY reqs.ID_RICHIESTA_RA, udoc.ID_STRUT
)
SELECT 
    ensia.id_ente_siam,
    ensia.nm_ente_siam,
    en.nm_ente || ' - ' || strut_ud.nm_strut,
    ra.ID_RICHIESTA_RA,
    amb.ID_AMBIENTE,
    en.ID_ENTE,
    s.ID_STRUT,
    s.totali,
    s.estratti,
    s.errori,
    CAST(s.sum_dim_raw / 1048576 AS NUMBER(20, 2)) AS dime,
    s.max_dt,
    ra.TI_STATO,
    CAST((s.estratti * 100 / NULLIF(s.totali, 0)) AS NUMBER(10, 2)) AS ESTRATTI_TOTALI,
    ra.cd_errore,
    ra.ts_inizio
FROM stats s
JOIN aro_richiesta_ra ra ON ra.ID_RICHIESTA_RA = s.ID_RICHIESTA_RA
JOIN org_strut strut_ud ON s.ID_STRUT = strut_ud.ID_STRUT
JOIN org_ente en ON en.id_ente = strut_ud.id_ente
JOIN org_ambiente amb ON amb.id_ambiente = en.id_ambiente
JOIN org_strut stru ON ra.ID_STRUT = stru.ID_STRUT
JOIN sacer_iam.org_ente_siam ensia ON stru.id_Ente_convenz = ensia.id_ente_siam;

-- changeset root:1780310394991-411
CREATE OR REPLACE FORCE VIEW ELV_V_LIS_DOC_BY_ELENCO_NEW_DDN (ID_ELENCO_VERS, ID_UNITA_DOC, ID_STRUT_UNITA_DOC, CD_REGISTRO_KEY_UNITA_DOC, AA_KEY_UNITA_DOC, CD_KEY_UNITA_DOC, ID_TIPO_UNITA_DOC, ID_REGISTRO_UNITA_DOC, ID_SUB_STRUT, DS_KEY_ORD, TI_STATO_ELENCO_VERS, TI_STATO_CONSERVAZIONE, ID_DOC, ID_STRUT_DOC, DT_CREAZIONE_DOC, FL_FORZA_ACCETTAZIONE, FL_FORZA_CONSERVAZIONE, ID_TIPO_DOC, TI_DOC, PG_DOC, NI_ORD_DOC) AS SELECT 
     
        CASE
           WHEN doc.ti_creazione = 'VERSAMENTO_UNITA_DOC' THEN ud.id_elenco_vers
           ELSE doc.id_elenco_Vers
       END AS id_elenco_vers,
       ud.id_unita_doc,
       ud.id_strut                 AS id_strut_unita_doc,
       ud.cd_registro_key_unita_doc,
       ud.aa_key_unita_doc,
       ud.cd_key_unita_doc,
       ud.id_tipo_unita_doc,
       ud.id_registro_unita_doc,
       ud.id_sub_strut,
       ud.ds_key_ord,
       CASE
           WHEN doc.ti_creazione = 'VERSAMENTO_UNITA_DOC' THEN ud.ti_stato_ud_elenco_vers
           WHEN doc.ti_creazione = 'AGGIUNTA_DOCUMENTO' AND doc.ti_stato_doc_elenco_vers IS NOT NULL THEN doc.ti_stato_doc_elenco_vers
           ELSE ud.ti_stato_ud_elenco_vers
       END AS ti_stato_elenco_vers,
       ud.ti_stato_conservazione,
       doc.id_doc,
       doc.id_strut                 AS id_strut_doc,
       doc.dt_creazione,
       doc.fl_forza_accettazione,
       doc.fl_forza_conservazione,
       doc.id_tipo_doc,
       doc.ti_doc,
       doc.pg_doc,
       doc.ni_ord_doc
  FROM ARO_UNITA_DOC ud
       JOIN ARO_DOC doc 
       ON doc.id_unita_doc = ud.id_unita_doc
 WHERE doc.ti_creazione IN ('VERSAMENTO_UNITA_DOC', 'AGGIUNTA_DOCUMENTO');

