-- changeset root:1780310394991-414 splitStatements:true
CREATE OR REPLACE FORCE VIEW ARO_V_RIC_PROP_SCARTO_VERS (ID_USER_IAM, ID_AMBIENTE, NM_AMBIENTE, ID_ENTE, NM_ENTE, ID_STRUT, NM_STRUT, ID_PROP_SCARTO_VERS, CD_PROP_SCARTO_VERS, DS_PROP_SCARTO_VERS, NT_PROP_SCARTO_VERS, DT_CREAZIONE_PROP_SCARTO_VERS, DT_ULTIMA_MOD_PROP_SCARTO_VERS, TI_STATO_PROP_SCARTO_VERS_COR) AS SELECT
    -- Profilazione Utente (necessario per filtrare i dati a cui l'utente ha accesso)
    abil_org.id_user_iam,

    -- Gerarchia Organizzativa (per alimentare le combo Ambiente/Ente/Struttura)
    amb.id_ambiente, amb.nm_ambiente,
    ente.id_ente, ente.nm_ente,
    strut.id_strut, strut.nm_strut,

    -- Dati della Proposta di Scarto
    prop.id_prop_scarto_vers,
    -- CREAZIONE VIRTUALE DEL CODICE (Progressivo/Anno)
    (LPAD (TO_CHAR(prop.pg_prop_scarto_vers), 10, '0') || '/' || TO_CHAR(prop.aa_prop_scarto_vers)) as cd_prop_scarto_vers,
    prop.ds_prop_scarto_vers,
    prop.nt_prop_scarto_vers,
    prop.dt_creazione as dt_creazione_prop_scarto_vers,
    prop.dt_ultima_mod as dt_ultima_mod_prop_scarto_vers,

    -- Stato corrente della proposta
    stato.ti_stato_prop_scarto_vers as ti_stato_prop_scarto_vers_cor

FROM ARO_PROP_SCARTO_VERS prop

-- JOIN per risalire l'albero organizzativo (filtrando gli enti/strutture cessati)
JOIN ORG_STRUT strut
  ON (strut.id_strut = prop.id_strut AND strut.fl_cessato = 0)
JOIN ORG_ENTE ente
  ON (ente.id_ente = strut.id_ente AND ente.fl_cessato = 0)
JOIN ORG_AMBIENTE amb
  ON (amb.id_ambiente = ente.id_ambiente)

-- JOIN per la visibilità del dato da parte dell'utente loggato
JOIN IAM_ABIL_ORGANIZ abil_org
  ON (abil_org.id_organiz_applic = strut.id_strut)

-- JOIN per appiattire lo stato corrente
JOIN ARO_STATO_PROP_SCARTO_VERS stato
  ON (stato.id_stato_prop_scarto_vers = prop.id_stato_prop_scarto_vers_cor);
COMMENT ON TABLE ARO_V_RIC_PROP_SCARTO_VERS IS 'Vista per la ricerca delle proposte di scarto versamenti';

-- changeset root:1780310394991-415
COMMENT ON COLUMN ARO_V_RIC_PROP_SCARTO_VERS.ID_USER_IAM IS 'PK.1';

-- changeset root:1780310394991-416
COMMENT ON COLUMN ARO_V_RIC_PROP_SCARTO_VERS.ID_PROP_SCARTO_VERS IS 'PK.2';

