-- changeset root:1780310394991-425
CREATE OR REPLACE FORCE VIEW ARO_V_LIS_DM_UD_DEL (ID_UNITA_DOC, AA_KEY_UNITA_DOC, CD_KEY_UNITA_DOC, CD_REGISTRO_KEY_UNITA_DOC, DT_VERSAMENTO, ID_ENTE, NM_ENTE, ID_STRUT, NM_STRUT, ID_RICHIESTA, CD_RICHIESTA, TI_MOT_CANCELLAZIONE, DT_CREAZIONE, TI_STATO_RICHIESTA, TI_STATO_UD_CANCELLATE, ID_RICH_SOFT_DELETE) AS WITH log_group AS (
  SELECT
    item_rich.id_unita_doc,
    item_rich.id_rich_soft_delete,
    log_rich.nm_child_table,
    log_rich.ni_level,
    SUM(log_rich.updated_row_count) AS updated_row_count_sum
  FROM sacer.aro_item_rich_soft_delete item_rich
  JOIN sacer.aro_log_rich_soft_delete log_rich
    ON log_rich.id_item_rich_soft_delete = item_rich.id_item_rich_soft_delete
  WHERE
    item_rich.ti_stato_item = 'ELABORATO'
    AND item_rich.ti_item_rich_soft_delete = 'UNI_DOC'
  GROUP BY
    item_rich.id_unita_doc,
    item_rich.id_rich_soft_delete,
    log_rich.nm_child_table,
    log_rich.ni_level
),
ud_counts AS (
  SELECT
    ud_del_rec_ref.id_unita_doc,
    ud_del_rec_ref.nm_tab     AS nm_child_table,
    ud_del_rec_ref.ni_livello AS ni_level,
    COUNT(*)                  AS num_item_pronti
  FROM sacer.dm_ud_del_rec_ref_tab ud_del_rec_ref
  GROUP BY
    ud_del_rec_ref.id_unita_doc,
    ud_del_rec_ref.nm_tab,
    ud_del_rec_ref.ni_livello
),
item_counts AS (
  SELECT
    g.id_unita_doc,
    g.id_rich_soft_delete,
    g.nm_child_table,
    g.ni_level,
    g.updated_row_count_sum                                   AS updated_row_count,
    COALESCE(c.num_item_pronti, 0)                            AS num_item_pronti,
    CASE
      WHEN g.updated_row_count_sum = COALESCE(c.num_item_pronti, 0)
        THEN 'CANCELLABILE'
      ELSE 'NON_CANCELLABILE'
    END                                                       AS stato_child_table
  FROM log_group g
  LEFT JOIN ud_counts c
    ON c.id_unita_doc   = g.id_unita_doc
   AND c.nm_child_table = g.nm_child_table
   AND c.ni_level       = g.ni_level
)
SELECT
    ud_del.id_unita_doc,
    ud_del.aa_key_unita_doc,
    ud_del.cd_key_unita_doc,
    ud_del.cd_registro_key_unita_doc,
    ud_del.dt_versamento,
    ud_del.id_ente,
    ud_del.nm_ente,
    ud_del.id_strut,
    ud_del.nm_strut,
    ud_del_rich.id_richiesta,
    ud_del_rich.cd_richiesta,
    ud_del_rich.ti_mot_cancellazione,
    ud_del_rich.dt_creazione,
    ud_del_rich.ti_stato_richiesta,
    CASE
        -- PRIORITÀ 1: Se lo stato fisico nella tabella DM_UD_DEL è già "Cancellata", mostra quello.
        WHEN ud_del.ti_stato_ud_cancellate = 'CANCELLATA_DB_SACER'
        THEN 'CANCELLATA_DB_SACER'

        -- PRIORITÀ 2 (comportamento precedente): Altrimenti, calcola lo stato basandoti sul lavoro di Kafka.
        WHEN COUNT(ic.id_unita_doc) = 0
        THEN 'DA_CANCELLARE'
        ELSE 
            CASE
                WHEN COUNT(ic.id_unita_doc) = SUM(CASE WHEN ic.stato_child_table = 'CANCELLABILE' THEN 1 ELSE 0 END)
                THEN 'CANCELLABILE'
                ELSE 'DA_CANCELLARE'
            END    
    END AS ti_stato_ud_cancellate,
    ic.id_rich_soft_delete
FROM 
sacer.dm_ud_del_richieste ud_del_rich
JOIN sacer.dm_ud_del ud_del
  ON (ud_del_rich.id_richiesta = ud_del.id_richiesta AND ud_del_rich.ti_mot_cancellazione = ud_del.ti_mot_cancellazione)
LEFT JOIN item_counts ic 
  ON IC.id_unita_doc = ud_del.id_unita_doc
GROUP BY  
    ud_del.id_unita_doc, 
    ud_del.ti_stato_ud_cancellate,
    ud_del.aa_key_unita_doc,
    ud_del.cd_key_unita_doc, 
    ud_del.cd_registro_key_unita_doc, 
    ud_del.dt_versamento, 
    ud_del.id_ente,
    ud_del.nm_ente, 
    ud_del.id_strut, 
    ud_del.nm_strut, 
    ud_del_rich.id_richiesta,
    ud_del_rich.cd_richiesta,
    ud_del_rich.ti_mot_cancellazione,
    ud_del_rich.dt_creazione,
    ud_del_rich.ti_stato_richiesta,
    ic.id_rich_soft_delete;

