-- changeset root:1780310394991-367
CREATE OR REPLACE FORCE VIEW ARO_V_LIS_ITEM_RA (ID_RICHIESTA_RA, ID_STRUT, ANNO, TOT_UD, NUM_AIP, DIMENSIONE, NUM_DOCS, NUM_ERRORI, NUM_ESTRATTI, AVANZAMENTO) AS SELECT a."ID_RICHIESTA",
           a."ID_STRUT",
           a."ANNO",
           a."TOT",
           a."NUM_AIP",
           a."dimensione",
           a."NUM_DOCUMENTI",
           a."NUM_ERRORI",
           a."NUM_ESTRATTI",
           CAST ((a.num_estratti * 100 / a.num_aip) AS NUMBER (10, 2))    "AVANZAMENTO"
      FROM (  SELECT ra.id_richiesta_ra
                         ID_RICHIESTA,
                     ud.id_strut,
                     ud.aa_key_unita_doc
                         ANNO,
                     COUNT (ud.id_unita_doc)
                         tot,
                     COUNT (aip.id_indice_aip)
                         num_aip,
                     CAST (SUM (ra.dim) / 1048576 AS NUMBER (20, 2))
                         "dimensione",
                       SUM (ni_annot)
                     + SUM (ni_annessi)
                     + SUM (ni_alleg)
                     + COUNT (DISTINCT aip.id_indice_aip)
                         "NUM_DOCUMENTI",
                     SUM (CASE ra.ti_stato WHEN 'ERRORE' THEN 1 ELSE 0 END)
                         NUM_ERRORI,
                     SUM (CASE ra.ti_stato WHEN 'ESTRATTO' THEN 1 ELSE 0 END)
                         num_estratti
                FROM aro_indice_aip_ud aip
                     JOIN aro_unita_doc ud
                         ON ud.id_unita_doc = aip.id_unita_doc
                     JOIN aro_aip_restituzione_archivio ra
                         ON ra.id_indice_aip = aip.id_indice_aip
            GROUP BY ra.id_richiesta_ra, ud.aa_key_unita_doc, ud.id_strut) a
    UNION ALL
    SELECT ID_RICHIESTA_RA,
           ID_STRUT,
           ANNO,
           TOT_UD,
           NUM_AIP,
           DIMENSIONE,
           NUM_DOCS,
           NUM_ERRORI,
           NUM_ESTRATTI,
           AVANZAMENTO
      FROM aro_lis_item_ra_foto;

-- changeset root:1780310394991-368
CREATE OR REPLACE FORCE VIEW ARO_V_LIS_ITEM_RICH_SCARTO (ID_ITEM_RICH_SCARTO_VERS, ID_RICH_SCARTO_VERS, PG_ITEM_RICH_SCARTO_VERS, DS_KEY_ITEM, TI_STATO_ITEM_SCARTO, DT_CREAZIONE, ID_UNITA_DOC, DS_LISTA_ERR, CD_REGISTRO_KEY_UNITA_DOC, AA_KEY_UNITA_DOC, CD_KEY_UNITA_DOC) AS select 
item_rich.id_item_rich_scarto_vers,
item_rich.id_rich_scarto_vers,
item_rich.pg_item_rich_scarto_vers,

item_rich.cd_registro_key_unita_doc || '-' || item_rich.aa_key_unita_doc || '-' || item_rich.cd_key_unita_doc ds_key_item,

item_rich.ti_stato_item_scarto,
ud.dt_creazione,
item_rich.id_unita_doc,

case
	when exists (select *
				 from ARO_ERR_RICH_SCARTO_VERS err_rich
				 where err_rich.id_item_rich_scarto_vers = item_rich.id_item_rich_scarto_vers
				)
		then (select listagg (err_rich.ti_err || '-' || err_rich.ds_err, '; ') within group (order by err_rich.ti_err) 
			  from ARO_ERR_RICH_SCARTO_VERS err_rich
			  where err_rich.id_item_rich_scarto_vers = item_rich.id_item_rich_scarto_vers
			  )
end ds_lista_err,
item_rich.cd_registro_key_unita_doc,
item_rich.aa_key_unita_doc,
item_rich.cd_key_unita_doc

from ARO_ITEM_RICH_SCARTO_VERS item_rich
left join ARO_UNITA_DOC ud
 on (ud.id_unita_doc = item_rich.id_unita_doc);

-- changeset root:1780310394991-369
CREATE OR REPLACE FORCE VIEW ARO_V_LIS_STATO_RICH_SCARTO (ID_RICH_SCARTO_VERS, ID_STATO_RICH_SCARTO_VERS, PG_STATO_RICH_SCARTO_VERS, TI_STATO_RICH_SCARTO_VERS, DT_REG_STATO_RICH_SCARTO_VERS, DS_NOTA_RICH_SCARTO_VERS, NM_USERID) AS select
stato_rich.id_rich_scarto_vers,
stato_rich.id_stato_rich_scarto_vers,
stato_rich.pg_stato_rich_scarto_vers,
stato_rich.ti_stato_rich_scarto_vers,
stato_rich.dt_reg_stato_rich_scarto_vers,
stato_rich.ds_nota_rich_scarto_vers,
usr.nm_userid
	
from ARO_STATO_RICH_SCARTO_VERS stato_rich

join IAM_USER usr
 on (usr.id_user_iam = stato_rich.id_user_iam);

-- changeset root:1780310394991-370
CREATE OR REPLACE FORCE VIEW ARO_V_RIC_RICH_SCARTO (ID_USER_IAM, ID_AMBIENTE, NM_AMBIENTE, ID_ENTE, NM_ENTE, ID_STRUT, NM_STRUT, ID_RICH_SCARTO_VERS, CD_RICH_SCARTO_VERS, DS_RICH_SCARTO_VERS, NT_RICH_SCARTO_VERS, DT_CREAZIONE_RICH_SCARTO_VERS, TI_CREAZIONE_RICH_SCARTO_VERS, TI_STATO_RICH_SCARTO_VERS_COR, ID_ITEM_RICH_SCARTO_VERS, CD_REGISTRO_KEY_UNITA_DOC, AA_KEY_UNITA_DOC, CD_KEY_UNITA_DOC, FL_NON_SCARTABILE, NI_ITEM, NI_ITEM_NON_SCARTATI) AS select
abil_org.id_user_iam,

amb.id_ambiente, amb.nm_ambiente,
ente.id_ente, ente.nm_ente,
strut.id_strut, strut.nm_strut,

rich.id_rich_scarto_vers,
rich.cd_rich_scarto_vers,
rich.ds_rich_scarto_vers,
rich.nt_rich_scarto_vers,
rich.dt_creazione_rich_scarto_vers,
rich.ti_creazione_rich_scarto_vers,

stato_rich.ti_stato_rich_scarto_vers ti_stato_rich_scarto_vers_cor,

item_rich.id_item_rich_scarto_vers,
item_rich.cd_registro_key_unita_doc,
item_rich.aa_key_unita_doc,
item_rich.cd_key_unita_doc,
case
	when exists (select * 
				 from ARO_ITEM_RICH_SCARTO_VERS item_non_scarto
				 where item_non_scarto.id_rich_scarto_vers = rich.id_rich_scarto_vers
				 and item_non_scarto.ti_stato_item_scarto = 'NON_SCARTABILE'
				)
		then '1'
		else '0'
end fl_non_scartabile,

(
    -- Conteggio da ARO_ITEM_RICH_SCARTO_VERS
    (select count(*)
     from ARO_ITEM_RICH_SCARTO_VERS item
     where item.id_rich_scarto_vers = rich.id_rich_scarto_vers)
    +
    -- MEV #39187: Conteggio aggiunto da DM_UD_DEL
    (select count(*)
     from DM_UD_DEL ud_del JOIN DM_UD_DEL_RICHIESTE ud_rich on (ud_del.id_ud_del_richiesta = ud_rich.id_ud_del_richiesta)
     where ud_rich.ID_RICHIESTA = rich.id_rich_scarto_vers AND ud_rich.ti_mot_cancellazione = 'S' AND ud_del.ti_stato_ud_cancellate = 'CANCELLATA_DB_SACER')
) ni_item,

(select count(*)
 from ARO_ITEM_RICH_SCARTO_VERS item
 where item.id_rich_scarto_vers = rich.id_rich_scarto_vers
 and item.ti_stato_item_scarto = 'NON_SCARTABILE'
) ni_item_non_scartati


from ARO_RICH_SCARTO_VERS rich

join ORG_STRUT strut
 on (strut.id_strut = rich.id_strut and strut.fl_cessato = 0)
join ORG_ENTE ente
 on (ente.id_ente = strut.id_ente )
join ORG_AMBIENTE amb
 on (amb.id_ambiente = ente.id_ambiente and ente.fl_cessato = 0)
 
join IAM_ABIL_ORGANIZ abil_org
 on (abil_org.id_organiz_applic = strut.id_strut)
 
join ARO_STATO_RICH_SCARTO_VERS stato_rich
 on (stato_rich.id_stato_rich_scarto_vers = rich.id_stato_rich_scarto_vers_cor)

left join ARO_ITEM_RICH_SCARTO_VERS item_rich
 on (item_rich.id_rich_scarto_vers = rich.id_rich_scarto_vers);

-- changeset root:1780310394991-371
CREATE OR REPLACE FORCE VIEW ARO_V_RIC_UNITA_DOC_RIC_DS (ID_UNITA_DOC, ID_STRUT_UNITA_DOC, CD_REGISTRO_KEY_UNITA_DOC, AA_KEY_UNITA_DOC, CD_KEY_UNITA_DOC, ID_SUB_STRUT, DT_CREAZIONE, FL_UNITA_DOC_FIRMATO, TI_ESITO_VERIF_FIRME, DS_MSG_ESITO_VERIF_FIRME, ID_TIPO_UNITA_DOC, ID_STRUT_TIPO_UNITA_DOC, NM_TIPO_UNITA_DOC, FL_FORZA_ACCETTAZIONE, FL_FORZA_CONSERVAZIONE, DS_KEY_ORD, DL_OGGETTO_UNITA_DOC, DT_REG_UNITA_DOC, TI_CONSERVAZIONE, NM_SISTEMA_MIGRAZ, NI_ALLEG, NI_ANNESSI, NI_ANNOT, ID_TIPO_DOC, NM_TIPO_DOC_PRINC, TI_STATO_CONSERVAZIONE, TI_STATO_UD_ELENCO_VERS, DS_LISTA_STATI_ELENCO_VERS) AS SELECT /*+ parallel */
           -- colonne unità documentaria
           ud.id_unita_doc,
           ud.id_strut                                     id_strut_unita_doc,
           ud.cd_registro_key_unita_doc,
           ud.aa_key_unita_doc,
           ud.cd_key_unita_doc,
           ud.id_sub_strut,
           ud.dt_creazione,
           ud.fl_unita_doc_firmato,
           ud.ti_esito_verif_firme,
           ud.ds_msg_esito_verif_firme,
           ud.id_tipo_unita_doc,
           tipo_unita_doc.id_strut                         id_strut_tipo_unita_doc,
           tipo_unita_doc.nm_tipo_unita_doc,
           ud.fl_forza_accettazione,
           ud.fl_forza_conservazione,
           ud.ds_key_ord,
           ud.dl_oggetto_unita_doc,
           ud.dt_reg_unita_doc,
           ud.ti_conservazione,
           ud.nm_sistema_migraz,
           ud.ni_alleg,
           ud.ni_annessi,
           ud.ni_annot,
           -- ===============================================================================
           doc.id_tipo_doc,
           (SELECT tipo_doc_princ.nm_tipo_doc
              FROM ARO_DOC  doc_princ
                   JOIN DEC_TIPO_DOC tipo_doc_princ
                       ON (tipo_doc_princ.id_tipo_doc = doc_princ.id_tipo_doc)
             WHERE     doc_princ.id_unita_doc = ud.id_unita_doc
                   AND doc_princ.ti_doc = 'PRINCIPALE')    nm_tipo_doc_princ,
           --  colonne aggiunte

           ud.ti_stato_conservazione,
           ud.ti_stato_ud_elenco_vers,
           (SELECT LISTAGG (tmp.ti_stato_elenco_vers, '; ')
                       WITHIN GROUP (ORDER BY tmp.ti_stato_elenco_vers)
              FROM (SELECT ud_elenco.ti_stato_ud_elenco_vers    ti_stato_elenco_vers
                      FROM ARO_UNITA_DOC ud_elenco
                     WHERE ud_elenco.id_unita_doc = ud.id_unita_doc
                    UNION 
                    SELECT 
                           doc_elenco.ti_stato_doc_elenco_vers    ti_stato_elenco_vers
                      FROM ARO_DOC doc_elenco
                     WHERE     doc_elenco.id_unita_doc = ud.id_unita_doc
                           AND doc_elenco.ti_stato_doc_elenco_vers
                                   IS NOT NULL) tmp)       ds_lista_stati_elenco_vers
      FROM ARO_UNITA_DOC  ud
           JOIN DEC_TIPO_UNITA_DOC tipo_unita_doc
               ON (tipo_unita_doc.id_tipo_unita_doc = ud.id_tipo_unita_doc)
           JOIN ARO_DOC doc ON (doc.id_unita_doc = ud.id_unita_doc);

-- changeset root:1780310394991-372
CREATE OR REPLACE FORCE VIEW ARO_V_VIS_COMP (NM_AMBIENTE, NM_ENTE, NM_STRUT, ID_UNITA_DOC, ID_STRUT_UNITA_DOC, CD_REGISTRO_KEY_UNITA_DOC, AA_KEY_UNITA_DOC, CD_KEY_UNITA_DOC, CD_KEY_UNITA_DOC_NORMALIZ, ID_TIPO_UNITA_DOC, NM_TIPO_UNITA_DOC, DT_ANNUL_UNITA_DOC, TI_ANNUL_UNITA_DOC, DL_OGGETTO_UNITA_DOC, DT_REG_UNITA_DOC, DT_CREAZIONE_UD, NT_ANNUL_UNITA_DOC, ID_DOC, CD_KEY_DOC_VERS, TI_DOC, PG_DOC, NM_TIPO_DOC, DL_DOC, DS_AUTORE_DOC, DT_ANNUL_DOC, TI_ANNUL_DOC, DT_CREAZIONE_DOC, TI_STATO_DOC, NM_TIPO_STRUT_DOC, NT_ANNUL_DOC, NI_ORD_DOC, ID_COMP_DOC, NI_ORD_COMP_DOC, NM_TIPO_COMP_DOC, TI_SUPPORTO_COMP, DS_NOME_COMP_VERS, DS_HASH_FILE_VERS, DL_URN_COMP_VERS, DS_ID_COMP_VERS, NM_FORMATO_VERS, NM_TIPO_RAPPR_COMP, TM_RIF_TEMP_VERS, DS_RIF_TEMP_VERS, FL_RIF_TEMP_DATA_FIRMA_VERS, NI_ORD_COMP_PADRE, FL_NO_CALC_FMT_VERIF_FIRME, FL_NO_CALC_HASH_FILE, DS_URN_COMP_CALC, NM_FORMATO_CALC, NI_SIZE_FILE_CALC, DS_HASH_FILE_CALC, DS_ALGO_HASH_FILE_CALC, CD_ENCODING_HASH_FILE_CALC, DS_HASH_FILE_256, DS_ALGO_HASH_FILE_256, CD_ENCODING_HASH_FILE_256, TI_ESITO_CONTR_FORMATO_FILE, DS_MSG_ESITO_CONTR_FORMATO, DS_FORMATO_RAPPR_CALC, DS_FORMATO_RAPPR_ESTESO_CALC, DS_FORMATO_RAPPR_FILE_DOC, FL_COMP_FIRMATO, TI_ESITO_VERIF_FIRME, DS_MSG_ESITO_VERIF_FIRME, NM_MIMETYPE_FILE, DS_URN_ORIGINALE, DS_URN_NORMALIZZATO, ID_VOLUME_CONSERV, NM_VOLUME_CONSERV, TI_STATO_VOLUME_CONSERV, DT_CHIUS_VOLUME, TI_ESITO_VERIF_FIRME_CHIUS, DS_ESITO_VERIF_FIRME_CHIUS, ID_ELENCO_VERS, NM_ELENCO_VERS, TI_STATO_ELENCO_VERS, DT_CHIUS_ELENCO_VERS, TI_ESITO_VERIF_FIRME_DT_VERS, DS_ESITO_VERIF_FIRME_DT_VERS, CD_REGISTRO_KEY_UNITA_DOC_RIF, AA_KEY_UNITA_DOC_RIF, CD_KEY_UNITA_DOC_RIF, TIPO_ARCHIVIAZIONE, CD_SUB_PARTITION, ID_FILE_ORACLE, NM_TENANT, NM_BUCKET, CD_KEY_FILE, DS_NOME_FILE_ARK, TI_STATO_DT_VERS, DS_SERVIZIO_VERIFICA_COMP_DOC) AS select
 amb.nm_ambiente,
 ente.nm_ente,
 strut.nm_strut,

-- info unit¿¿ documentaria
 ud.id_unita_doc,
 ud.id_strut, 
 ud.cd_registro_key_unita_doc, ud.aa_key_unita_doc, ud.cd_key_unita_doc, ud.cd_key_unita_doc_normaliz,
 tipo_ud.id_tipo_unita_doc, tipo_ud.nm_tipo_unita_doc, 
 ud.dt_annul dt_annul_unita_doc,
 ud.ti_annul ti_annul_unita_doc,
 ud.dl_oggetto_unita_doc,
 ud.dt_reg_unita_doc,
 ud.dt_creazione dt_creazione_ud,
 ud.nt_annul nt_annul_unita_doc,

 
-- info documento 
 doc.id_doc,
 doc.cd_key_doc_vers,
 doc.ti_doc,
 doc.pg_doc,
 tipo_doc.nm_tipo_doc,
 doc.dl_doc, doc.ds_autore_doc, 
 doc.dt_annul dt_annul_doc,
 doc.ti_annul ti_annul_doc,

 doc.dt_creazione dt_creazione_doc,
 doc.ti_stato_doc,
 tipo_strut_doc.nm_tipo_strut_doc,
